<h1>Backups</h1><div class="card"><h2>Provider status</h2><p><b>Provider:</b> <?= e(config('guard.backup_provider','disabled')) ?> · <b>Root:</b> <code><?= e($service->root()) ?></code> · <b>Browser:</b> <?= config('guard.backup_browser_enabled')?'enabled':'disabled' ?> · <b>Web restore:</b> <?= config('guard.backup_restore_enabled')?'enabled':'disabled' ?></p><p><b>ISPmanager detected:</b> <?= $detect['mgr5_exists']?'yes':'no' ?> · <b>Backup root exists:</b> <?= $detect['root_exists']?'yes':'no' ?></p><?php if($detect['tools']): ?><p><b>Detected tools:</b></p><pre><?= e(implode("\n", $detect['tools'])) ?></pre><?php endif ?></div>
<div class="grid"><div class="card"><h2>Users</h2><ul><?php foreach($users as $u): ?><li><a href="/backups?user=<?= urlencode($u) ?>"><?= e($u) ?></a></li><?php endforeach ?></ul></div><div class="card"><h2>Backup dates</h2><table><tr><th>User</th><th>Date</th><th>Type</th><th>Path</th></tr><?php foreach($backups as $b): ?><tr><td><?= e($b['user']) ?></td><td><?= e($b['date']) ?></td><td><?= e($b['type']) ?></td><td><code><?= e($b['path']) ?></code></td></tr><?php endforeach ?></table></div></div>
