<?php if($preview !== null): ?><div class="card"><h2>Preview / Diff</h2><p><b>Current file:</b> <code><?= e($searchPath) ?></code></p><p><b>Backup date:</b> <?= e($date) ?></p><h3>Diff</h3><pre><?= e($diff) ?></pre><h3>Backup preview</h3><pre><?= e($preview) ?></pre><?php $cmd='php artisan guard:backups:restore-file --path='.escapeshellarg($searchPath).' --date='.escapeshellarg($date); ?><h3>Restore</h3><?php if(!config('guard.backup_restore_enabled')): ?><p class="muted">Web restore is disabled. Run this CLI command after confirmation:</p><pre><?= e($cmd) ?></pre><?php else: ?><p>Use CLI for audited selective restore: <code><?= e($cmd) ?></code></p><?php endif ?></div><?php endif ?>
